-- D.Pharm Forensic and Community Pharmacy: bilingual foundational learning content
-- NPC-oriented study support. Verify current Nepal laws, DDA notices and NPC syllabus before exam use.
-- Run after secure-content.sql and pharmacy-faculties-phase1.sql. Safe to re-run.

insert into public.learning_content
(content_id,faculty,subject,content_type,access_tier,display_order,content_data,is_published)
values
('dph-fcp-note-101','Pharmacy','Diploma in Pharmacy','note','free',1101,
'{"title":"Introduction to Forensic Pharmacy and Pharmacy Law","english":"Forensic pharmacy deals with the legal and ethical aspects of pharmacy practice, including medicine regulation, professional responsibilities, documentation and accountability. Pharmacy professionals must work within the scope of their qualification and authorization, follow current national laws and regulations, maintain required records and cooperate with regulatory authorities. In Nepal, learners should study the latest applicable provisions and notices issued by the Department of Drug Administration (DDA), Nepal Pharmacy Council (NPC) and other competent authorities. Do not rely on outdated schedules or unofficial summaries for legal decisions.","nepali":"Forensic pharmacy ले pharmacy practice का कानुनी तथा नैतिक पक्षहरू अध्ययन गर्छ, जस्तै औषधि नियमन, पेशागत जिम्मेवारी, अभिलेख र जवाफदेहिता। Pharmacy professional ले आफ्नो योग्यता र अधिकारभित्र रहेर काम गर्नुपर्छ, हाल लागू राष्ट्रिय कानुन तथा नियम पालना गर्नुपर्छ, आवश्यक अभिलेख राख्नुपर्छ र नियामक निकायसँग सहकार्य गर्नुपर्छ। नेपालमा DDA, NPC तथा सम्बन्धित सक्षम निकायका पछिल्ला कानुनी व्यवस्था र सूचनाहरू अध्ययन गर्नुहोस्। कानुनी निर्णयका लागि पुराना schedule वा अप्रमाणित सारांशमा भर नपर्नुहोस्।"}'::jsonb,true),
('dph-fcp-note-102','Pharmacy','Diploma in Pharmacy','note','free',1102,
'{"title":"Prescription Medicines, Restricted Medicines and Record Keeping","english":"Medicines may be subject to different legal controls depending on their category and applicable national rules. A pharmacy must verify that a prescription is valid where one is required, check the prescriber and order details, dispense only within legal authority and maintain records required by current law. Medicines subject to special controls may have additional requirements for storage, supply, registers, prescriptions and stock reconciliation. Always consult the latest official legal text and DDA directions for the current classification and procedures; never guess a schedule, quantity limit or penalty.","nepali":"औषधिको वर्ग र लागू राष्ट्रिय नियमअनुसार औषधिमा फरक कानुनी नियन्त्रण हुन सक्छ। Prescription आवश्यक पर्ने औषधि वितरण गर्दा prescription वैध छ कि छैन, prescriber र औषधिको विवरण ठीक छ कि छैन जाँच्नुपर्छ। कानुनी अधिकारभित्र मात्र वितरण गरी हालको कानुनले मागेका अभिलेख राख्नुपर्छ। विशेष नियन्त्रण भएका औषधिमा भण्डारण, बिक्री, register, prescription र stock मिलानसम्बन्धी थप नियम हुन सक्छन्। हालको वर्गीकरण र प्रक्रिया जान्न आधिकारिक कानुनी पाठ तथा DDA का पछिल्ला निर्देशन हेर्नुहोस्; schedule, मात्रा सीमा वा सजाय अनुमान नगर्नुहोस्।"}'::jsonb,true),
('dph-fcp-note-103','Pharmacy','Diploma in Pharmacy','note','free',1103,
'{"title":"Professional Ethics, Good Dispensing Practice and Patient Rights","english":"Ethical pharmacy practice requires honesty, confidentiality, respect, non-discrimination, competence and putting patient safety first. Protect personal health information and share it only when legally permitted or necessary for care. Do not falsify prescriptions or records, promote irrational medicine use, or dispense outside professional authority. Explain medicine use clearly, disclose relevant limitations, refer patients when a problem is beyond your competence and report errors or safety concerns through appropriate channels.","nepali":"नैतिक pharmacy practice मा इमानदारी, गोपनीयता, सम्मान, भेदभाव नगर्ने व्यवहार, दक्षता र बिरामीको सुरक्षा प्राथमिकता पर्छन्। बिरामीको व्यक्तिगत स्वास्थ्य सूचना सुरक्षित राख्नुपर्छ र कानुनले अनुमति दिएको वा उपचारका लागि आवश्यक अवस्थामा मात्र साझा गर्नुपर्छ। Prescription वा अभिलेख झुटो बनाउनु, अनावश्यक औषधि प्रयोग प्रोत्साहन गर्नु वा आफ्नो अधिकारबाहिर औषधि वितरण गर्नु हुँदैन। औषधि प्रयोग स्पष्ट बुझाउने, आफ्नो सीमाबारे जानकारी दिने, आफ्नो दक्षताभन्दा बाहिरको समस्या भए referral गर्ने र गल्ती वा सुरक्षा जोखिम उचित माध्यमबाट रिपोर्ट गर्ने गर्नुपर्छ।"}'::jsonb,true),
('dph-fcp-note-104','Pharmacy','Diploma in Pharmacy','note','free',1104,
'{"title":"Community Pharmacy and Public Health Services","english":"Community pharmacies are accessible health-service points that support appropriate medicine use and public health. Within their authorized scope, services may include dispensing, patient counselling, adherence support, basic health information, referral, health promotion and participation in approved public-health programmes. A community pharmacy should encourage rational use of medicines, discourage sharing or unnecessary use of antibiotics, identify danger signs and refer patients to an appropriate health facility. Services such as screening or testing must follow applicable authorization, training and protocols.","nepali":"Community pharmacy समुदायमा सजिलै पहुँच हुने स्वास्थ्य सेवा केन्द्र हो, जसले औषधिको उचित प्रयोग र जनस्वास्थ्यमा सहयोग गर्छ। आफ्नो अधिकारभित्र dispensing, बिरामी परामर्श, औषधि नियमित प्रयोगमा सहयोग, आधारभूत स्वास्थ्य जानकारी, referral, स्वास्थ्य प्रवर्द्धन र स्वीकृत जनस्वास्थ्य कार्यक्रममा सहभागिता हुन सक्छ। Community pharmacy ले औषधिको विवेकपूर्ण प्रयोग प्रोत्साहन गर्नुपर्छ, antibiotic बाँडेर खाने वा अनावश्यक प्रयोग निरुत्साहित गर्नुपर्छ, खतराका संकेत पहिचान गरी उपयुक्त स्वास्थ्य संस्थामा पठाउनुपर्छ। Screening वा testing सेवा अनुमति, तालिम र protocol अनुसार मात्र गर्नुपर्छ।"}'::jsonb,true),
('dph-fcp-note-105','Pharmacy','Diploma in Pharmacy','note','free',1105,
'{"title":"Rational Use of Medicines, Pharmacovigilance and Referral","english":"Rational use means that patients receive medicines appropriate to their clinical needs, in suitable doses, for an adequate period and at an affordable cost. Avoid unnecessary antibiotics, inappropriate self-medication, sharing medicines and stopping long-term treatment without professional advice. Pharmacovigilance is the science and activities related to detecting, assessing, understanding and preventing adverse effects or other medicine-related problems. Suspected adverse drug reactions should be documented and reported through the current national or institutional reporting system. Urgent symptoms require prompt referral or emergency care.","nepali":"Rational use of medicines भन्नाले बिरामीले आफ्नो clinical आवश्यकता अनुसार उपयुक्त औषधि, सही मात्रा, पर्याप्त अवधि र वहन गर्न सकिने लागतमा पाउनु हो। अनावश्यक antibiotic, अनुचित self-medication, औषधि अरूलाई बाँड्ने र पेशागत सल्लाहबिना दीर्घकालीन औषधि बन्द गर्ने कामबाट बच्नुपर्छ। Pharmacovigilance भनेको औषधिका adverse effect तथा अन्य औषधिसम्बन्धी समस्याको पहिचान, मूल्याङ्कन, बुझाइ र रोकथामसम्बन्धी विज्ञान तथा गतिविधि हो। शंकास्पद adverse drug reaction अभिलेख गरी हाल लागू राष्ट्रिय वा संस्थागत प्रणालीबाट रिपोर्ट गर्नुपर्छ। आकस्मिक लक्षण भए तुरुन्त referral वा emergency care आवश्यक हुन्छ।"}'::jsonb,true),
('dph-fcp-mcq-101','Pharmacy','Diploma in Pharmacy','mcq','free',1101,
'{"question":"Forensic pharmacy mainly deals with which aspect of pharmacy practice?","translation":"Forensic pharmacy ले मुख्यतः pharmacy practice को कुन पक्ष अध्ययन गर्छ?","options":["Legal and ethical aspects","Only tablet coating","Only plant taxonomy","Only hospital building design"],"correctIndex":0,"explanation":"Forensic pharmacy covers legal, regulatory and ethical responsibilities in pharmacy practice.","explanationNe":"Forensic pharmacy ले pharmacy practice का कानुनी, नियामक र नैतिक जिम्मेवारी समेट्छ।"}'::jsonb,true),
('dph-fcp-mcq-102','Pharmacy','Diploma in Pharmacy','mcq','free',1102,
'{"question":"Which authority regulates medicines in Nepal?","translation":"नेपालमा औषधि नियमन गर्ने निकाय कुन हो?","options":["Department of Drug Administration (DDA)","Department of Roads","Nepal Electricity Authority","Election Commission"],"correctIndex":0,"explanation":"The Department of Drug Administration is Nepal’s national medicines regulatory authority.","explanationNe":"औषधि व्यवस्था विभाग (DDA) नेपालमा औषधि नियमन गर्ने राष्ट्रिय निकाय हो।"}'::jsonb,true),
('dph-fcp-mcq-103','Pharmacy','Diploma in Pharmacy','mcq','free',1103,
'{"question":"What should a pharmacy professional do if the legal status of a medicine is uncertain?","translation":"कुनै औषधिको कानुनी स्थिति अस्पष्ट भए pharmacy professional ले के गर्नुपर्छ?","options":["Guess its legal category","Check current official rules or seek regulatory guidance","Dispense it to everyone","Ignore documentation"],"correctIndex":1,"explanation":"Current official legal texts and regulatory guidance should be checked rather than guessing.","explanationNe":"अनुमान गर्नुको सट्टा हालको आधिकारिक कानुनी व्यवस्था वा नियामक निर्देशन जाँच्नुपर्छ।"}'::jsonb,true),
('dph-fcp-mcq-104','Pharmacy','Diploma in Pharmacy','mcq','free',1104,
'{"question":"Which is an example of professional pharmacy ethics?","translation":"पेशागत pharmacy ethics को उदाहरण कुन हो?","options":["Maintaining patient confidentiality","Sharing patient details casually","Falsifying dispensing records","Dispensing beyond legal authority"],"correctIndex":0,"explanation":"Protecting patient confidentiality is a core professional and ethical responsibility.","explanationNe":"बिरामीको गोपनीयता कायम राख्नु पेशागत तथा नैतिक मुख्य जिम्मेवारी हो।"}'::jsonb,true),
('dph-fcp-mcq-105','Pharmacy','Diploma in Pharmacy','mcq','free',1105,
'{"question":"A patient asks for an antibiotic without an appropriate prescription where one is legally required. What is the best response?","translation":"कानुनअनुसार prescription चाहिने antibiotic बिरामीले उपयुक्त prescription बिना मागेमा के गर्नु उचित हुन्छ?","options":["Supply it immediately","Follow current law, explain and refer for proper assessment","Sell a larger quantity","Ask the patient to share someone else’s prescription"],"correctIndex":1,"explanation":"Follow current legal requirements and guide the patient to appropriate clinical assessment.","explanationNe":"हालको कानुनी व्यवस्था पालना गरी बिरामीलाई उचित clinical assessment का लागि पठाउनुपर्छ।"}'::jsonb,true),
('dph-fcp-mcq-106','Pharmacy','Diploma in Pharmacy','mcq','free',1106,
'{"question":"Community pharmacy contributes to public health by:","translation":"Community pharmacy ले जनस्वास्थ्यमा कसरी योगदान दिन्छ?","options":["Providing appropriate counselling and referral","Encouraging unnecessary antibiotics","Promoting medicine sharing","Avoiding health information"],"correctIndex":0,"explanation":"Counselling, rational medicine-use education and referral are important community pharmacy contributions.","explanationNe":"परामर्श, औषधिको विवेकपूर्ण प्रयोगसम्बन्धी शिक्षा र referral community pharmacy का महत्त्वपूर्ण योगदान हुन्।"}'::jsonb,true),
('dph-fcp-mcq-107','Pharmacy','Diploma in Pharmacy','mcq','free',1107,
'{"question":"Rational use of medicines means:","translation":"औषधिको विवेकपूर्ण प्रयोग भन्नाले के बुझिन्छ?","options":["Appropriate medicine for the clinical need, dose and duration","Taking antibiotics for every fever","Stopping treatment whenever symptoms improve","Using another person’s medicines"],"correctIndex":0,"explanation":"Rational use matches treatment to clinical need, correct dose and adequate duration.","explanationNe":"Rational use मा clinical आवश्यकता अनुसार सही औषधि, मात्रा र पर्याप्त अवधि मिलाइन्छ।"}'::jsonb,true),
('dph-fcp-mcq-108','Pharmacy','Diploma in Pharmacy','mcq','free',1108,
'{"question":"Pharmacovigilance is concerned with:","translation":"Pharmacovigilance कुन विषयसँग सम्बन्धित छ?","options":["Detecting and preventing medicine-related harm","Designing pharmacy furniture","Counting hospital beds","Marketing without safety review"],"correctIndex":0,"explanation":"Pharmacovigilance detects, assesses, understands and helps prevent adverse effects and other medicine-related problems.","explanationNe":"Pharmacovigilance ले औषधिका adverse effect तथा अन्य समस्याको पहिचान, मूल्याङ्कन, बुझाइ र रोकथाममा काम गर्छ।"}'::jsonb,true),
('dph-fcp-mcq-109','Pharmacy','Diploma in Pharmacy','mcq','free',1109,
'{"question":"What is an appropriate action when a patient has danger signs beyond the pharmacy professional’s scope?","translation":"बिरामीमा आफ्नो कार्यक्षेत्रभन्दा बाहिरका खतराका संकेत देखिए के गर्नुपर्छ?","options":["Promptly refer to an appropriate health facility","Delay care and observe for several days","Give any available medicine","Ignore the symptoms"],"correctIndex":0,"explanation":"Recognize limits of competence and arrange prompt referral or emergency care when needed.","explanationNe":"आफ्नो दक्षताको सीमा पहिचान गरी आवश्यकताअनुसार तुरुन्त referral वा emergency care मिलाउनुपर्छ।"}'::jsonb,true),
('dph-fcp-mcq-110','Pharmacy','Diploma in Pharmacy','mcq','free',1110,
'{"question":"Which action supports safe handling of a suspected adverse drug reaction?","translation":"शंकास्पद adverse drug reaction को सुरक्षित व्यवस्थापनमा कुन काम सहयोगी हुन्छ?","options":["Document and report through the appropriate system","Delete all related records","Ignore the event if mild","Change the patient’s prescription independently"],"correctIndex":0,"explanation":"Documenting and reporting suspected ADRs supports pharmacovigilance and patient safety.","explanationNe":"शंकास्पद ADR अभिलेख र उचित प्रणालीबाट रिपोर्ट गर्दा pharmacovigilance तथा बिरामी सुरक्षा बलियो हुन्छ।"}'::jsonb,true),
('dph-fcp-mock-101','Pharmacy','Diploma in Pharmacy','mock','free',1101,
'{"question":"Define forensic pharmacy and mention four areas it covers.","answer":"Forensic pharmacy studies legal and ethical aspects of pharmacy practice. Areas include medicine regulation, professional scope and responsibilities, prescription and dispensing requirements, documentation, accountability and regulatory compliance.","answerNe":"Forensic pharmacy ले pharmacy practice का कानुनी तथा नैतिक पक्ष अध्ययन गर्छ। यसमा औषधि नियमन, पेशागत कार्यक्षेत्र र जिम्मेवारी, prescription तथा dispensing का नियम, अभिलेख, जवाफदेहिता र नियामक पालना पर्छन्।"}'::jsonb,true),
('dph-fcp-mock-102','Pharmacy','Diploma in Pharmacy','mock','free',1102,
'{"question":"Explain why a pharmacy must follow current medicine laws and maintain required records.","answer":"Current laws define which activities and supplies are permitted and the safeguards needed for public safety. Accurate records support traceability, accountability, stock control, inspections and investigation of medicine-related problems.","answerNe":"हालको कानुनले कुन काम र औषधि वितरण अनुमति छ तथा जनसुरक्षाका लागि के सावधानी चाहिन्छ भन्ने निर्धारण गर्छ। सही अभिलेखले traceability, जवाफदेहिता, stock control, निरीक्षण र औषधिसम्बन्धी समस्याको अनुसन्धानमा सहयोग गर्छ।"}'::jsonb,true),
('dph-fcp-mock-103','Pharmacy','Diploma in Pharmacy','mock','free',1103,
'{"question":"Describe five ethical responsibilities of a community pharmacy professional.","answer":"Maintain confidentiality, respect patients and avoid discrimination, provide accurate information, work within professional competence and legal authority, protect patient safety, document appropriately and refer when needed.","answerNe":"गोपनीयता कायम गर्ने, बिरामीलाई सम्मान गर्ने र भेदभाव नगर्ने, सही जानकारी दिने, आफ्नो दक्षता तथा कानुनी अधिकारभित्र काम गर्ने, बिरामी सुरक्षा प्राथमिकता दिने, उचित अभिलेख राख्ने र आवश्यक परे referral गर्ने।"}'::jsonb,true),
('dph-fcp-mock-104','Pharmacy','Diploma in Pharmacy','mock','free',1104,
'{"question":"What is rational use of medicines? Give three examples of practices that promote it.","answer":"Rational use means patients receive medicines appropriate to their clinical needs, in suitable doses, for adequate duration and at affordable cost. Promote it by counselling on correct use, discouraging unnecessary antibiotics and medicine sharing, and referring patients for proper assessment when needed.","answerNe":"Rational use भनेको बिरामीले clinical आवश्यकता अनुसार उपयुक्त औषधि, सही मात्रा, पर्याप्त अवधि र वहन गर्न सकिने लागतमा पाउनु हो। सही प्रयोगबारे परामर्श दिने, अनावश्यक antibiotic तथा औषधि बाँडेर खाने काम निरुत्साहित गर्ने र आवश्यक परे उचित जाँचका लागि पठाउने यसका उदाहरण हुन्।"}'::jsonb,true),
('dph-fcp-mock-105','Pharmacy','Diploma in Pharmacy','mock','free',1105,
'{"question":"Define pharmacovigilance and outline how a suspected adverse drug reaction should be handled.","answer":"Pharmacovigilance is the detection, assessment, understanding and prevention of adverse effects or other medicine-related problems. Record relevant details, ensure the patient receives appropriate care, notify the responsible clinician when needed and report through the current national or institutional system using its required process.","answerNe":"Pharmacovigilance भनेको औषधिका adverse effect तथा अन्य औषधिसम्बन्धी समस्याको पहिचान, मूल्याङ्कन, बुझाइ र रोकथाम हो। सम्बन्धित विवरण अभिलेख गर्ने, बिरामीलाई उचित care सुनिश्चित गर्ने, आवश्यक परे जिम्मेवार clinician लाई जानकारी दिने र हालको राष्ट्रिय वा संस्थागत प्रणालीबाट तोकिएको प्रक्रियाअनुसार रिपोर्ट गर्ने।"}'::jsonb,true)
on conflict (content_id) do update set
faculty=excluded.faculty, subject=excluded.subject, content_type=excluded.content_type,
access_tier=excluded.access_tier, display_order=excluded.display_order,
content_data=excluded.content_data, is_published=excluded.is_published;
